/**
 * Accessibility registry and checks. Zero dependencies; shared by validate.mjs,
 * new-component.mjs and the docs site (apps/docs/src/lib/a11y.ts).
 *
 * Registry (specs/a11y/):
 *   sources.json  trusted publishers (URL prefixes) + conformance target
 *   wcag.json     WCAG 2.2 success criteria, GENERATED by scripts/a11y-wcag.mjs
 *   roles.json    per component role: obligations backed by trusted references
 *
 * A spec cites sources through `refs`: either "wcag:<sc>" (e.g. "wcag:2.5.8") or the id of an
 * entry in its own `accessibility.references[]`.
 */
import fs from 'node:fs';
import path from 'node:path';
import { FILES } from './paths.mjs';

const LEVELS = ['A', 'AA', 'AAA'];

export function loadA11y(root) {
  const read = (f) => JSON.parse(fs.readFileSync(path.join(root, FILES.a11y, f), 'utf8'));
  return { sources: read('sources.json'), wcag: read('wcag.json'), roles: read('roles.json').roles };
}

/** Publisher id whose prefix matches the URL, or null when the URL is not a trusted source. */
export function trustedPublisher(url, registry) {
  for (const [id, p] of Object.entries(registry.sources.publishers)) {
    if (p.prefixes.some((prefix) => url.startsWith(prefix))) return id;
  }
  return null;
}

export function criterion(sc, registry) {
  const c = registry.wcag.criteria[sc];
  if (!c) return null;
  const target = registry.sources.conformanceTarget.level;
  return {
    sc,
    ...c,
    url: registry.wcag.understanding.replace('{slug}', c.slug),
    inTarget: c.level !== null && LEVELS.indexOf(c.level) <= LEVELS.indexOf(target),
  };
}

/** SC number from a WCAG 2.2 Understanding or Recommendation URL, or null. */
export function criterionFromUrl(url, registry) {
  const m = url.match(/^https:\/\/www\.w3\.org\/(?:WAI\/WCAG22\/Understanding\/([a-z0-9-]+)\.html|TR\/WCAG22\/#([a-z0-9-]+))/);
  const slug = m?.[1] ?? m?.[2];
  if (!slug) return null;
  return Object.entries(registry.wcag.criteria).find(([, c]) => c.slug === slug)?.[0] ?? null;
}

/** Resolve one ref of a spec to { ref, title, url, publisher, kind, criterion? } or null. */
export function resolveRef(ref, spec, registry) {
  if (ref.startsWith('wcag:')) {
    const c = criterion(ref.slice(5), registry);
    if (!c) return null;
    return { ref, title: `WCAG ${c.sc} ${c.title} (${c.level ?? 'removed'})`, url: c.url, publisher: 'wcag-guidance', kind: 'guidance', criterion: c };
  }
  const r = (spec.accessibility?.references ?? []).find((x) => x.id === ref);
  if (!r) return null;
  const publisher = trustedPublisher(r.url, registry);
  return { ref, title: r.title, url: r.url, publisher, kind: publisher ? registry.sources.publishers[publisher].kind : null };
}

/** Every statement of the accessibility section, plus every decision and contrast requirement citing sources, with a label for messages. */
export function citedStatements(spec) {
  const a = spec.accessibility ?? {};
  const out = [];
  if (a.name) out.push({ where: 'accessibility.name', refs: a.name.refs ?? [] });
  (a.keyboard ?? []).forEach((k, i) => out.push({ where: `accessibility.keyboard[${i}] (${k.key})`, refs: k.refs ?? [] }));
  (a.guidelines ?? []).forEach((g, i) => out.push({ where: `accessibility.guidelines[${i}]`, refs: g.refs ?? [] }));
  (spec.decisions ?? []).forEach((d) => { if (d.refs) out.push({ where: `decision "${d.id}"`, refs: d.refs }); });
  (spec.contrast ?? []).forEach((c) => out.push({ where: `contrast "${c.id}"`, refs: c.refs ?? [] }));
  return out;
}

/** Sorted WCAG criteria cited anywhere in the accessibility section. */
export function citedCriteria(spec, registry) {
  const scs = new Set();
  for (const s of citedStatements(spec)) for (const r of s.refs) if (r.startsWith('wcag:')) scs.add(r.slice(5));
  const num = (sc) => sc.split('.').map((n) => n.padStart(3, '0')).join('.');
  return [...scs].sort((a, b) => num(a).localeCompare(num(b))).map((sc) => criterion(sc, registry)).filter(Boolean);
}

/**
 * Spec-level accessibility checks (no file access). Returns [{ level: 'error' | 'warn', message }].
 */
export function checkSpecA11y(spec, registry) {
  const problems = checkCitations(spec, registry);
  if (!spec.accessibility) return problems;
  const error = (message) => problems.push({ level: 'error', message });
  const a = spec.accessibility;

  // Role profile.
  const profile = registry.roles[spec.role];
  if (!profile) {
    error(`role "${spec.role}" has no accessibility profile in specs/a11y/roles.json; add one from its APG pattern and WAI-ARIA role before specifying the component`);
    return problems;
  }
  if (profile.ariaRole && a.ariaRole !== profile.ariaRole) error(`accessibility.ariaRole must be "${profile.ariaRole}" for role "${spec.role}" (got ${a.ariaRole === undefined ? 'nothing' : `"${a.ariaRole}"`})`);
  if (profile.nameRequired && !a.name) error(`role "${spec.role}" requires accessibility.name (how the accessible name is computed)`);
  const keys = new Set((a.keyboard ?? []).map((k) => k.key));
  for (const k of profile.keyboard ?? []) if (!keys.has(k)) error(`role "${spec.role}" requires a keyboard entry for "${k}"`);
  if (profile.focusable && !spec.states.some((s) => s.id === 'focus-visible')) error(`role "${spec.role}" is focusable: declare the "focus-visible" state (WCAG 2.4.7)`);
  const cited = new Set(citedCriteria(spec, registry).map((c) => c.sc));
  for (const [sc, why] of Object.entries(profile.requiredCriteria ?? {})) {
    if (!cited.has(sc)) error(`role "${spec.role}" requires WCAG ${sc} (${registry.wcag.criteria[sc]?.title}) to be cited: ${why}`);
  }
  return problems;
}

/**
 * Citation checks shared by component and foundation specs: every statement cites a source,
 * references are trusted and used, WCAG refs exist in WCAG 2.2.
 */
export function checkCitations(spec, registry) {
  const problems = [];
  const error = (message) => problems.push({ level: 'error', message });
  const warn = (message) => problems.push({ level: 'warn', message });
  const a = spec.accessibility;
  if (!a) return [{ level: 'error', message: 'accessibility section is required' }];

  // References: unique ids, trusted URLs, all used.
  const refIds = (a.references ?? []).map((r) => r.id);
  if (new Set(refIds).size !== refIds.length) error('duplicate ids in accessibility.references');
  for (const r of a.references ?? []) {
    if (!trustedPublisher(r.url, registry)) error(`reference "${r.id}" (${r.url}) is not a trusted source; use a publisher from specs/a11y/sources.json`);
  }
  const used = new Set();
  for (const s of citedStatements(spec)) {
    if (s.refs.length === 0) error(`${s.where} cites no source`);
    for (const ref of s.refs) {
      used.add(ref);
      if (ref.startsWith('wcag:')) {
        const c = registry.wcag.criteria[ref.slice(5)];
        if (!c) error(`${s.where} cites unknown WCAG success criterion ${ref}`);
        else if (!c.inWcag22) error(`${s.where} cites ${ref} (${c.title}), which is not part of WCAG ${registry.wcag.version}`);
      } else if (!refIds.includes(ref)) {
        error(`${s.where} cites "${ref}", which is neither "wcag:<sc>" nor an id in accessibility.references`);
      }
    }
  }
  for (const id of refIds) if (!used.has(id)) warn(`accessibility.references "${id}" is never cited`);
  return problems;
}

/** Registry self-check: role profiles cite trusted sources and existing WCAG 2.2 criteria. */
export function checkRegistry(registry) {
  const problems = [];
  const error = (message) => problems.push({ level: 'error', message });
  const { level } = registry.sources.conformanceTarget;
  if (!LEVELS.includes(level)) error(`sources.json conformanceTarget.level "${level}" must be one of ${LEVELS.join(', ')}`);
  for (const [role, p] of Object.entries(registry.roles)) {
    if (!p.references?.length) error(`roles.json "${role}" cites no references`);
    for (const r of p.references ?? []) if (!trustedPublisher(r.url, registry)) error(`roles.json "${role}" cites ${r.url}, which is not a trusted source`);
    for (const sc of Object.keys(p.requiredCriteria ?? {})) {
      const c = registry.wcag.criteria[sc];
      if (!c?.inWcag22) error(`roles.json "${role}" requires ${sc}, which is not a WCAG ${registry.wcag.version} success criterion`);
    }
  }
  return problems;
}

/** Content of the "## Accessibility" section of a Markdown page, or null. */
export function docsAccessibilitySection(markdown) {
  const m = markdown.match(/^## Accessibility[ \t]*\n([\s\S]*?)(?=^## |(?![\s\S]))/m);
  return m ? m[1] : null;
}

/** Docs checks: a sourced Accessibility section, trusted links only, WCAG links consistent with the spec. */
export function checkDocsA11y(markdown, spec, registry) {
  const problems = [];
  const error = (message) => problems.push({ level: 'error', message });
  const section = docsAccessibilitySection(markdown);
  if (section === null) return [{ level: 'error', message: 'needs a "## Accessibility" section' }];
  const links = [...section.matchAll(/\]\((https?:[^)\s]+)\)/g)].map((m) => m[1]);
  if (links.length === 0) error('the Accessibility section must link the trusted sources that back it');
  const cited = new Set(citedCriteria(spec, registry).map((c) => c.sc));
  for (const url of links) {
    if (!trustedPublisher(url, registry)) error(`Accessibility section links ${url}, which is not a trusted source (specs/a11y/sources.json)`);
    const sc = criterionFromUrl(url, registry);
    if (sc && !cited.has(sc)) error(`Accessibility section relies on WCAG ${sc} but the spec does not cite wcag:${sc}`);
  }
  return problems;
}

/** Drop elements hidden with aria-hidden="true", then tags; what remains approximates name from content (AccName 2A + 2F). */
export function visibleTextContent(html) {
  let prev;
  let out = html;
  do {
    prev = out;
    out = out.replace(/<([a-z][a-z0-9-]*)\b[^>]*\baria-hidden="true"[^>]*>[\s\S]*?<\/\1>/gi, '');
  } while (out !== prev);
  return out.replace(/<[^>]+>/g, '').replace(/&[a-z]+;/g, ' ').trim();
}
